// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address deployer;

    function setUp() public { c = new StaxLPStaking(address(this), address(this)); deployer = address(this); }

    function testFuzz_property(address someAddr) public {
        vm.assume(someAddr != address(0));

        bool ok;
        try c.owner() returns (address o) {
            ok = (o == deployer);
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
